safe_remediated_config:
# [REMEDIATED] Palo Alto Security Policy with explicit App-ID and Threat Prevention
resource "panos_security_policy" "remediated_analytics_egress" {
  rule {
    name                  = "Allow-Analytics-Outbound-Webhook-Remediated"
    source_zones          = ["Trust-DMZ"]
    source_addresses      = ["10.100.4.0/24"]
    source_users          = ["any"]
    destination_zones     = ["Untrust-Internet"]
    destination_addresses = ["52.84.120.0/22"] # Scoped to verified partner CIDR
    applications          = ["ssl", "web-browsing"] # Layer 7 App-ID enforced
    services              = ["service-https"]
    action                = "allow"
    security_profile_group = "corporate-threat-prevention-standard"
  }
}

# [REMEDIATED] Scoped Least-Privilege IAM Policy for Telemetry Ingestion
resource "aws_iam_policy" "scoped_telemetry_s3_write" {
  name        = "pol-telemetry-staging-write-only"
  description = "Scoped write-only access to unclassified telemetry bucket"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action   = ["s3:PutObject", "s3:AbortMultipartUpload"]
      Effect   = "Allow"
      Resource = "arn:aws:s3:::apex-telemetry-staging-us-east-1/*"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "scoped_analytics_attachment" {
  role       = "role-analytics-ingestion-svc"
  policy_arn = aws_iam_policy.scoped_telemetry_s3_write.arn
}
